import { formatEuros } from './money.js';
import { invoiceTotals, lineTotal } from './invoices.js';
import { getCustomer } from './customers.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, dueDate?: string, payments?: Array<{ amount: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // First line: number or DRAFT
  const numberLine = invoice.number ?? 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build line items
  const lineItems = invoice.lines.map((line) => {
    const total = lineTotal(line);
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const totalFormatted = formatEuros(total);
    let lineText = `${line.qty}x ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;

    // Add discount if present
    const discountPercent = line.discountPercent ?? 0;
    if (discountPercent > 0) {
      const discount = roundCents(total * discountPercent / 100);
      const discountFormatted = formatEuros(discount);
      lineText += ` (${discountPercent}% off: -${discountFormatted})`;
    }

    return lineText;
  });

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Build output lines
  const lines = [numberLine, customerName, ...lineItems];

  // Add voucher if present
  if (invoice.voucher) {
    const voucherFormatted = formatEuros(invoice.voucher.amount);
    lines.push(`Voucher ${invoice.voucher.code}: -${voucherFormatted}`);
  }

  // Add VAT and total
  const vatFormatted = formatEuros(totals.vat);
  const totalFormatted = formatEuros(totals.total);
  lines.push(`VAT: ${vatFormatted}`);
  lines.push(`Total: ${totalFormatted}`);

  // Add due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    const paidFormatted = formatEuros(totalPaid);
    lines.push(`Paid: ${paidFormatted}`);
  }

  return lines.join('\n');
}

