test('renderInvoiceText: voucher appears before VAT/Total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.strictEqual(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const voucherResult = applyVoucher(invoice, { code: 'TEST', amount: 1000 });
  const invoiceWithVoucher = voucherResult.value;

  const text = renderInvoiceText(invoiceWithVoucher);
  const lines = text.split('\n');

  // Find indices
  const voucherIdx = lines.findIndex((l) => l.includes('Voucher'));
  const vatIdx = lines.findIndex((l) => l.startsWith('VAT:'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));

  // Voucher should come before VAT and Total
  assert.ok(voucherIdx < vatIdx);
  assert.ok(vatIdx < totalIdx);
});

